{
  "root_causes": [
    {
      "service": "ts-preserve-service",
      "fault_kind": "http_aborted",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, count(*) n, round(quantile_cont(duration,0.5)/1e6,1) p50_ms FROM abnormal_traces WHERE service_name='ts-preserve-service' AND attr_span_kind='Client' AND span_name='POST' GROUP BY ALL",
          "claim": "All 242 of preserve's outgoing POST calls end in Error with no status code; none succeed in the abnormal window."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, attr_http_response_status_code sc, count(*) n, round(quantile_cont(duration,0.5)/1e6,1) p50_ms FROM abnormal_traces WHERE service_name='ts-travel-service' AND span_name='POST /api/v1/travelservice/trip_detail' GROUP BY ALL",
          "claim": "ts-travel-service trip_detail server spans still return 200 with normal-looking durations, so the called side is not failing itself."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, count(*) n FROM abnormal_logs WHERE service_name='ts-preserve-service' AND message LIKE '%Unexpected end of file from server%' GROUP BY ALL",
          "claim": "Preserve logs SEVERE exceptions: I/O error on POST to ts-travel-service trip_detail, 'Unexpected end of file from server'."
        },
        {
          "kind": "metric",
          "sql": "SELECT attr_source, attr_destination, metric, round(avg(value),2) avg_v FROM abnormal_metrics_sum WHERE metric IN ('hubble_drop_total') AND attr_source LIKE '%preserve-service%' GROUP BY ALL",
          "claim": "Hubble drop counters on the preserve→travel connection show no drops; the failure is not packet loss on the wire."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-preserve-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, attr_http_response_status_code sc, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-preserve-service' AND attr_span_kind='Server' AND span_name LIKE '%preserve%' GROUP BY ALL",
          "claim": "Preserve's own server span returns HTTP 500 on every request, with p95 around 2.2 s, and ui-dashboard relays these failures to the user."
        }
      ]
    }
  ]
}
